import locVectorData from './vector.json';

// The vector JSONs are generated by export_vector_json.py from the trained model
// artifacts (*_vector*.npy + *_meta.json). Do not edit by hand.
//
// One deployment now serves several feeds, each ranked by its own trained vector
// (see feeds.ts), so scoring is a factory rather than a module-level singleton:
// `createScorer(vectorData)` closes over one vector's weights and calibration and
// returns both its scoring function and its fingerprint.

export type VectorData = {
  vector: number[];
  scale: number;
  bias: number;
  embedding_model?: string;
  embedding_task?: string;
};

export type Scorer = {
  /** Cosine + calibrated sigmoid probability for one embedding. */
  score(embedding: number[]): { cosine: number; probability: number };
  /** Fingerprint of this vector's parameters; see VECTOR_VERSION below. */
  version: string;
};

export function createScorer(data: VectorData): Scorer {
  const targetVector = data.vector;
  const SCALE = data.scale;
  const BIAS = data.bias;

  function score(embedding: number[]): { cosine: number; probability: number } {
    // L2 normalize
    let norm = 0;
    for (let i = 0; i < embedding.length; i++) {
      norm += embedding[i] * embedding[i];
    }
    norm = Math.sqrt(norm);
    if (norm < 1e-12) norm = 1e-12;

    // Dot product
    let cos = 0;
    for (let i = 0; i < targetVector.length; i++) {
      cos += (embedding[i] / norm) * targetVector[i];
    }

    // Sigmoid
    const probability = 1.0 / (1.0 + Math.exp(-(SCALE * cos + BIAS)));
    return { cosine: cos, probability };
  }

  return { score, version: fingerprint([...targetVector, SCALE, BIAS]) };
}

// --- Scoring-model fingerprint --------------------------------------------
//
// The feed caches the *score* each post gets (see post_scores), not the 1024-dim
// embedding it was derived from. That makes the cache key depend on the scoring
// model too: regenerating a vector JSON (export_vector_json.py, after a retrain)
// must invalidate every cached score, or the feed would keep serving the old
// model's verdicts forever.
//
// So we hash the raw parameters — weights, scale, bias — once per isolate and
// fold the result into the cache key. A retrain changes the hash, which changes
// the key, which turns every stale row into an ordinary cache miss. FNV-1a over
// each float's exact bit pattern; we only need "did this change?", so collision
// resistance is irrelevant. Note the per-feed probability threshold is
// deliberately NOT part of this: it is applied to the cached score at read time,
// so retuning a threshold costs nothing and keeps the warm cache.
//
// With several feeds live the fingerprint does a second job: it is what keeps
// two vectors' scores for the same post from colliding in the cache, since each
// vector hashes differently and the version is part of the row's key.
const _f32 = new Float32Array(1);
const _u8 = new Uint8Array(_f32.buffer);
function fingerprint(nums: number[]): string {
  let h = 0x811c9dc5 >>> 0;
  for (let i = 0; i < nums.length; i++) {
    _f32[0] = nums[i];
    for (let b = 0; b < 4; b++) {
      h = (h ^ _u8[b]) >>> 0;
      h = Math.imul(h, 0x01000193) >>> 0;
    }
  }
  return h.toString(16).padStart(8, '0');
}

// The locus-of-control scorer, kept as a module-level export so the existing
// callers (and test_pipeline_time.ts) keep working unchanged.
const locScorer = createScorer(locVectorData as VectorData);
export const scoreEmbedding = locScorer.score;
export const VECTOR_VERSION = locScorer.version;
